import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as r,ak as n}from"./chunks/framework.DC-k2h36.js";const s="/projects/esp32Sensor/en/latest/assets/1.DN7nWiLk.webp",i="/projects/esp32Sensor/en/latest/assets/2.B4CES6pC.webp",l="/projects/esp32Sensor/en/latest/assets/3.DvySLmNL.webp",c="/projects/esp32Sensor/en/latest/assets/4.55vH78aO.webp",_=JSON.parse('{"title":"8. Glowy Ultrasonic Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/8. Glowy Ultrasonic Sensor.md","filePath":"docs/8. Glowy Ultrasonic Sensor.md"}'),d={name:"docs/8. Glowy Ultrasonic Sensor.md"};function h(g,e,p,u,m,b){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_8-glowy-ultrasonic-sensor" tabindex="-1">8. Glowy Ultrasonic Sensor <a class="header-anchor" href="#_8-glowy-ultrasonic-sensor" aria-label="Permalink to &quot;8. Glowy Ultrasonic Sensor&quot;">​</a></h1><h2 id="_8-1-introduction" tabindex="-1">8.1 Introduction <a class="header-anchor" href="#_8-1-introduction" aria-label="Permalink to &quot;8.1 Introduction&quot;">​</a></h2><p>The glowy ultrasonic sensor is a distance-measuring module equipped with integrated RGB lights. It incorporates an industrial-grade ultrasonic ranging chip that integrates ultrasonic transmitting circuits, receiving circuits, and digital processing circuits. Operating via an I2C communication interface, the module allows the controller to read measured distance values over the I2C bus.</p><img loading="lazy" height="1387" width="1387" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_8-2-technical-specifications" tabindex="-1">8.2 Technical Specifications <a class="header-anchor" href="#_8-2-technical-specifications" aria-label="Permalink to &quot;8.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Operating frequency</td><td style="text-align:center;">40 kHz</td></tr><tr><td style="text-align:center;">Effective detection range</td><td style="text-align:center;">2–400 cm</td></tr><tr><td style="text-align:center;">Measuring angle</td><td style="text-align:center;">15°</td></tr><tr><td style="text-align:center;">Displayable colors</td><td style="text-align:center;">RGB colors</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">55.4 × 23.4 × 23.8 mm</td></tr></tbody></table><h2 id="_8-3-hands-on-project" tabindex="-1">8.3 Hands-On Project <a class="header-anchor" href="#_8-3-hands-on-project" aria-label="Permalink to &quot;8.3 Hands-On Project&quot;">​</a></h2><h3 id="_8-3-1-project-overview" tabindex="-1">8.3.1 Project Overview <a class="header-anchor" href="#_8-3-1-project-overview" aria-label="Permalink to &quot;8.3.1 Project Overview&quot;">​</a></h3><p>This project uses the integrated RGB lights of the glowy ultrasonic sensor and the onboard buzzer to provide audio and visual alerts for close-range obstacles. When the measured obstacle distance is less than 15 cm, the sensor RGB lights flash red twice while the buzzer sounds simultaneously. When the obstacle distance is 15 cm or greater, the sensor RGB lights stay green, and the buzzer turns off, illustrating ultrasonic distance acquisition, variable storage, loop execution, and conditional branch programming logic.</p><h3 id="_8-3-2-hardware-wiring" tabindex="-1">8.3.2 Hardware Wiring <a class="header-anchor" href="#_8-3-2-hardware-wiring" aria-label="Permalink to &quot;8.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the glowy ultrasonic sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="875" src="'+i+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_8-3-3-adding-extensions" tabindex="-1">8.3.3 Adding Extensions <a class="header-anchor" href="#_8-3-3-adding-extensions" aria-label="Permalink to &quot;8.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Glowy ultrasonic sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_8-3-4-complete-program-and-analysis" tabindex="-1">8.3.4 Complete Program and Analysis <a class="header-anchor" href="#_8-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;8.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the glowy ultrasonic sensor is initialized to port P1, and the integrated RGB lights of the sensor are turned off.</p></li><li><p>Inside the main program loop, the obstacle distance detected by the sensor is read and stored in the variable <code>Distance</code> to perform conditional judgment:</p><ul><li><p>If <code>Distance</code> is less than 15 cm, the sequence repeats 2 times, illuminating all sensor RGB lights in red, playing note C5 for half a beat in the background, waiting 0.2 s, and then turning off both the buzzer and the sensor RGB lights.</p></li><li><p>If <code>Distance</code> is greater than or equal to 15 cm, all sensor RGB lights are set to green, and the buzzer turns off.</p></li></ul></li><li><p>The program pauses for 0.1 s at the end of each loop before repeating the distance check.</p></li></ol><img loading="lazy" height="1026" width="719" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/08 Glowy Ultrasonic Sensor.sb3</a>.</strong></p></div><h3 id="_8-3-5-program-upload" tabindex="-1">8.3.5 Program Upload <a class="header-anchor" href="#_8-3-5-program-upload" aria-label="Permalink to &quot;8.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_8-3-6-program-outcome" tabindex="-1">8.3.6 Program Outcome <a class="header-anchor" href="#_8-3-6-program-outcome" aria-label="Permalink to &quot;8.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, the glowy ultrasonic sensor continuously measures the distance to objects ahead. When an object approaches the sensor within a distance of less than 15 cm, the sensor RGB lights flash red twice, and the buzzer sounds an alert tone. When the object moves farther away to a distance of 15 cm or greater, the sensor RGB lights remain solid green, and the buzzer stops sounding, delivering an interactive close-range obstacle warning system.</p>',25)])])}const w=a(d,[["render",h]]);export{_ as __pageData,w as default};
